class Solution:
    def maxArea(self, coords):
        n = len(coords)
        best = -1
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    (x1, y1), (x2, y2), (x3, y3) = coords[i], coords[j], coords[k]
                    if x1 == x2 or x1 == x3 or x2 == x3 or y1 == y2 or y1 == y3 or y2 == y3:
                        area2 = abs((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1))
                        if area2 > 0:
                            best = max(best, area2)
        return best

