public:
    long long maxArea(vector<vector<int>>& coords) {
        int n = coords.size(); long long best = -1;
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) for (int k = j + 1; k < n; k++) {
            auto &a = coords[i], &b = coords[j], &c = coords[k];
            bool ok = a[0]==b[0]||a[0]==c[0]||b[0]==c[0]||a[1]==b[1]||a[1]==c[1]||b[1]==c[1];
            if (!ok) continue;
            long long ar = llabs((long long)(b[0]-a[0])*(c[1]-a[1]) - (long long)(c[0]-a[0])*(b[1]-a[1]));
            if (ar > 0) best = max(best, ar);
        }
        return best;
    }
};

