class Solution:
    def maxArea(self, coords):
        from collections import defaultdict
        rows, cols = defaultdict(list), defaultdict(list)
        for x, y in coords:
            rows[y].append(x)
            cols[x].append(y)
        ymin = min(r for r in rows); ymax = max(r for r in rows)
        xmin = min(c for c in cols); xmax = max(c for c in cols)
        best = -1
        for y, lst in rows.items():
            if len(lst) > 1:
                h = max(abs(y - ymin), abs(y - ymax))
                if h:
                    best = max(best, (max(lst) - min(lst)) * h)
        for x, lst in cols.items():
            if len(lst) > 1:
                h = max(abs(x - xmin), abs(x - xmax))
                if h:
                    best = max(best, (max(lst) - min(lst)) * h)
        return best

