class Solution {
public:
    long long maxArea(vector<vector<int>>& coords) {
        unordered_map<int, pair<int,int>> rows, cols;
        int ymin = INT_MAX, ymax = INT_MIN, xmin = INT_MAX, xmax = INT_MIN;
        for (auto& p : coords) {
            int x = p[0], y = p[1];
            auto upd = [](unordered_map<int,pair<int,int>>& mp, int k, int v) {
                auto it = mp.find(k);
                if (it == mp.end()) mp[k] = {v, v};
                else { it->second.first = min(it->second.first, v); it->second.second = max(it->second.second, v); }
            };
            upd(rows, y, x); upd(cols, x, y);
            ymin = min(ymin, y); ymax = max(ymax, y);
            xmin = min(xmin, x); xmax = max(xmax, x);
        }
        long long best = -1;
        for (auto& [y, pr] : rows) {
            long long h = max(abs(y - ymin), abs(y - ymax));
            if (pr.second > pr.first && h) best = max(best, (long long)(pr.second - pr.first) * h);
        }
        for (auto& [x, pr] : cols) {
            long long h = max(abs(x - xmin), abs(x - xmax));
            if (pr.second > pr.first && h) best = max(best, (long long)(pr.second - pr.first) * h);
        }
        return best;
    }
};

