class Solution {
    public long maxArea(int[][] coords) {
        Map<Integer, int[]> rows = new HashMap<>(), cols = new HashMap<>();
        int ymin = Integer.MAX_VALUE, ymax = Integer.MIN_VALUE;
        int xmin = Integer.MAX_VALUE, xmax = Integer.MIN_VALUE;
        for (int[] p : coords) {
            rows.computeIfAbsent(p[1], k -> new int[]{p[0], p[0]});
            int[] r = rows.get(p[1]);
            r[0] = Math.min(r[0], p[0]); r[1] = Math.max(r[1], p[0]);
            cols.computeIfAbsent(p[0], k -> new int[]{p[1], p[1]});
            int[] c = cols.get(p[0]);
            c[0] = Math.min(c[0], p[1]); c[1] = Math.max(c[1], p[1]);
            ymin = Math.min(ymin, p[1]); ymax = Math.max(ymax, p[1]);
            xmin = Math.min(xmin, p[0]); xmax = Math.max(xmax, p[0]);
        }
        long best = -1;
        for (var e : rows.entrySet()) {
            int y = e.getKey(); int[] pr = e.getValue();
            long h = Math.max(Math.abs(y - ymin), Math.abs(y - ymax));
            if (pr[1] > pr[0] && h > 0) best = Math.max(best, (long)(pr[1] - pr[0]) * h);
        }
        for (var e : cols.entrySet()) {
            int x = e.getKey(); int[] pr = e.getValue();
            long h = Math.max(Math.abs(x - xmin), Math.abs(x - xmax));
            if (pr[1] > pr[0] && h > 0) best = Math.max(best, (long)(pr[1] - pr[0]) * h);
        }
        return best;
    }
}

