var maxArea = function(coords) {
    const rows = new Map(), cols = new Map();
    let ymin = Infinity, ymax = -Infinity, xmin = Infinity, xmax = -Infinity;
    for (const [x, y] of coords) {
        if (!rows.has(y)) rows.set(y, [x, x]);
        const r = rows.get(y); r[0] = Math.min(r[0], x); r[1] = Math.max(r[1], x);
        if (!cols.has(x)) cols.set(x, [y, y]);
        const c = cols.get(x); c[0] = Math.min(c[0], y); c[1] = Math.max(c[1], y);
        ymin = Math.min(ymin, y); ymax = Math.max(ymax, y);
        xmin = Math.min(xmin, x); xmax = Math.max(xmax, x);
    }
    let best = -1;
    for (const [y, pr] of rows) {
        const h = Math.max(Math.abs(y - ymin), Math.abs(y - ymax));
        if (pr[1] > pr[0] && h > 0) best = Math.max(best, (pr[1] - pr[0]) * h);
    }
    for (const [x, pr] of cols) {
        const h = Math.max(Math.abs(x - xmin), Math.abs(x - xmax));
        if (pr[1] > pr[0] && h > 0) best = Math.max(best, (pr[1] - pr[0]) * h);
    }
    return best;
};
